import type { DeviceType, Difficulty, GameEngine, LicenseType } from '@playverse/shared-types';
import type { CategorySlug } from './categories';

/**
 * The PLAYVERSE catalog roadmap. Every entry is a distinct, original game
 * concept implemented in-house (no third-party assets, no trademarked names).
 *
 * `batch` is the delivery batch from docs/ROADMAP.md. An entry only becomes
 * PUBLISHED (playable) once its runtime module exists, its launch flow has been
 * tested, and an admin publishes it — the seed never marks games playable.
 */
export interface CatalogGame {
  slug: string;
  title: string;
  category: CategorySlug;
  extraCategories?: CategorySlug[];
  difficulty: Difficulty;
  devices: DeviceType[];
  estimatedMinutes: number;
  engine: Extract<GameEngine, 'CANVAS' | 'DOM'>;
  summary: string;
  details: string;
  howToPlay: string;
  supportsScores: boolean;
  supportsProgress?: boolean;
  multiplayerMode?: 'local-2p';
  /** Key in @playverse/game-runtime's registry once a module exists. */
  runtimeKey?: string;
  featured?: boolean;
  batch: number;
  license: LicenseType;
}

const ALL: DeviceType[] = ['DESKTOP', 'TABLET', 'MOBILE'];
/** Needs a larger screen or a physical keyboard. */
const LARGE: DeviceType[] = ['DESKTOP', 'TABLET'];
const KEYBOARD: DeviceType[] = ['DESKTOP'];

type Entry = Omit<CatalogGame, 'license' | 'supportsScores'> & { supportsScores?: boolean };
const g = (entry: Entry): CatalogGame => ({ supportsScores: true, license: 'ORIGINAL', ...entry });

